/* Bank SKD tambahan (penutup celah audit relevansi). o[0] = jawaban benar (TWK/TIU), TKP urut skor 5,4,3,2,1. */
const BANK_TWK_2 = [
{t:"uud", q:"Penyerahan urusan pemerintahan oleh pemerintah pusat kepada daerah otonom berdasarkan asas otonomi disebut...", o:["Desentralisasi","Dekonsentrasi","Tugas pembantuan","Sentralisasi","Federalisasi"], p:"Menurut UU Nomor 23 Tahun 2014 tentang Pemerintahan Daerah, desentralisasi adalah penyerahan urusan pemerintahan dari pusat kepada daerah otonom. Dekonsentrasi dan tugas pembantuan bukan penyerahan, melainkan pelimpahan dan penugasan."},
{t:"uud", q:"Pelimpahan sebagian urusan pemerintah pusat kepada gubernur sebagai wakil pemerintah pusat di daerah disebut...", o:["Dekonsentrasi","Desentralisasi","Tugas pembantuan","Otonomi khusus","Sentralisasi"], p:"Dekonsentrasi adalah pelimpahan wewenang dari pemerintah pusat kepada gubernur sebagai wakil pusat atau kepada instansi vertikal di daerah. Pada desentralisasi, urusan diserahkan menjadi kewenangan daerah sendiri."},
{t:"uud", q:"Pemerintah pusat menugaskan pemerintah kabupaten melaksanakan sebagian urusan pusat disertai pendanaan dari pusat. Asas yang berlaku adalah...", o:["Tugas pembantuan","Desentralisasi","Dekonsentrasi","Otonomi seluas-luasnya","Otonomi khusus"], p:"Penugasan dari pusat kepada daerah untuk melaksanakan sebagian urusan pusat, dengan pembiayaan dari pusat, disebut tugas pembantuan. Urusannya tetap milik pusat sehingga daerah hanya melaksanakan."},
{t:"uud", q:"Berikut ini urusan pemerintahan absolut yang menjadi kewenangan pemerintah pusat menurut UU Nomor 23 Tahun 2014, KECUALI...", o:["Pendidikan","Politik luar negeri","Pertahanan","Keamanan","Moneter dan fiskal nasional"], p:"Enam urusan absolut adalah politik luar negeri, pertahanan, keamanan, yustisi, moneter dan fiskal nasional, serta agama. Pendidikan termasuk urusan konkuren yang dibagi antara pusat dan daerah."},
{t:"uud", q:"Menurut UU Nomor 23 Tahun 2014, pemerintahan daerah diselenggarakan oleh...", o:["Pemerintah daerah dan DPRD","Pemerintah pusat dan DPR","Gubernur dan MPR","DPD dan DPRD","Kepala daerah dan kejaksaan"], p:"Menurut UU 23/2014, pemerintahan daerah diselenggarakan oleh pemerintah daerah (kepala daerah) bersama DPRD, dengan dibantu perangkat daerah. DPR, MPR, dan DPD adalah lembaga tingkat nasional."},
{t:"uud", q:"DPR menggunakan hak ini untuk meminta keterangan kepada pemerintah tentang kebijakan penting dan strategis yang berdampak luas. Hak tersebut adalah...", o:["Hak interpelasi","Hak angket","Hak menyatakan pendapat","Hak imunitas","Hak mengajukan pertanyaan"], p:"Interpelasi adalah hak DPR untuk meminta keterangan kepada pemerintah. Hak angket berbeda karena berupa penyelidikan, sedangkan menyatakan pendapat adalah sikap DPR atas suatu kebijakan atau kejadian."},
{t:"uud", q:"Hak DPR untuk menyelidiki pelaksanaan undang-undang dan kebijakan pemerintah yang diduga bertentangan dengan peraturan disebut...", o:["Hak angket","Hak interpelasi","Hak menyatakan pendapat","Hak imunitas","Hak mengajukan usul"], p:"Angket adalah hak penyelidikan DPR terhadap kebijakan atau pelaksanaan undang-undang yang penting, strategis, dan diduga melanggar aturan. Interpelasi hanya meminta keterangan, belum menyelidiki."},
{t:"uud", q:"Pembahasan dan persetujuan DPR atas Rancangan Anggaran Pendapatan dan Belanja Negara merupakan pelaksanaan fungsi...", o:["Anggaran","Legislasi","Pengawasan","Yudisial","Eksekutif"], p:"Tiga fungsi DPR adalah legislasi (membuat undang-undang), anggaran (membahas dan menyetujui APBN), dan pengawasan (mengawasi pelaksanaan undang-undang dan kebijakan). Membahas APBN termasuk fungsi anggaran."},
{t:"uud", q:"Tokoh yang mengemukakan teori pemisahan kekuasaan negara menjadi legislatif, eksekutif, dan yudikatif (trias politica) adalah...", o:["Montesquieu","John Locke","Jean-Jacques Rousseau","Thomas Hobbes","Niccolo Machiavelli"], p:"Montesquieu dalam karyanya tentang semangat undang-undang menyusun pemisahan tiga kekuasaan secara tegas. Locke membahas pembagian kekuasaan lebih dahulu, tetapi pembagian tiga yang dikenal sebagai trias politica dikaitkan dengan Montesquieu."},
{t:"uud", q:"Salah satu ciri sistem pemerintahan presidensial adalah...", o:["Presiden menjadi kepala negara sekaligus kepala pemerintahan","Kepala pemerintahan dipilih oleh parlemen","Kabinet bertanggung jawab kepada parlemen","Kepala negara hanya bersifat simbolis","Menteri berasal dari anggota parlemen"], p:"Pada sistem presidensial, presiden memegang dua jabatan sekaligus (kepala negara dan kepala pemerintahan) dan menteri bertanggung jawab kepada presiden. Pilihan lain adalah ciri sistem parlementer."},
{t:"uud", q:"Lembaga yang berwenang memeriksa dan memutus dugaan pelanggaran kode etik penyelenggara pemilu adalah...", o:["DKPP","Bawaslu","KPU","Mahkamah Konstitusi","Mahkamah Agung"], p:"DKPP (Dewan Kehormatan Penyelenggara Pemilu) menangani pelanggaran kode etik penyelenggara pemilu. KPU menyelenggarakan pemilu, Bawaslu mengawasi dan menangani pelanggaran pemilu, sedangkan MK memutus sengketa hasil pemilu."},
{t:"sejarah", q:"Berikut ini negara pendiri ASEAN pada Deklarasi Bangkok 1967, KECUALI...", o:["Brunei Darussalam","Filipina","Singapura","Thailand","Malaysia"], p:"ASEAN didirikan pada 8 Agustus 1967 di Bangkok oleh lima negara: Indonesia, Malaysia, Filipina, Singapura, dan Thailand. Brunei Darussalam bergabung kemudian, pada tahun 1984."},
{t:"sejarah", q:"Salah satu isi Dasasila Bandung hasil Konferensi Asia Afrika 1955 adalah...", o:["Menghormati kedaulatan dan keutuhan wilayah semua bangsa","Membentuk pakta pertahanan bersama dengan negara besar","Mendukung salah satu blok dalam Perang Dingin","Ikut campur urusan dalam negeri negara lain demi stabilitas","Menyelesaikan sengketa dengan kekuatan senjata"], p:"Dasasila Bandung menegaskan penghormatan pada kedaulatan, persamaan semua bangsa, tidak mencampuri urusan dalam negeri negara lain, dan penyelesaian sengketa secara damai. Isinya menolak pakta pertahanan untuk kepentingan negara besar."},
{t:"sejarah", q:"Konferensi Tingkat Tinggi pertama Gerakan Non-Blok pada tahun 1961 diselenggarakan di kota...", o:["Beograd","Bandung","Kairo","New Delhi","Jenewa"], p:"KTT I Gerakan Non-Blok berlangsung di Beograd (Yugoslavia) pada 1961. Bandung adalah tempat Konferensi Asia Afrika 1955 yang menjadi cikal bakalnya."},
{t:"sejarah", q:"Pemilihan umum pertama di Indonesia tahun 1955 dilaksanakan dalam dua tahap untuk memilih...", o:["Anggota DPR dan anggota Konstituante","Presiden dan anggota DPR","Anggota DPR dan anggota DPRD","Anggota MPR dan Presiden","Gubernur dan anggota DPR"], p:"Pemilu 1955 digelar dua kali: 29 September untuk anggota DPR dan 15 Desember untuk anggota Konstituante. Presiden saat itu belum dipilih langsung."},
{t:"sejarah", q:"Dalam peristiwa Gerakan 30 September 1965, jenazah para perwira TNI AD yang diculik ditemukan di sebuah sumur di...", o:["Lubang Buaya","Rengasdengklok","Pegangsaan Timur","Taman Makam Pahlawan Kalibata","Cibubur"], p:"Jenazah para perwira TNI AD ditemukan di sumur tua kawasan Lubang Buaya, Jakarta Timur. Rengasdengklok adalah lokasi peristiwa menjelang proklamasi 1945."},
{t:"sejarah", q:"Surat Perintah 11 Maret 1966 (Supersemar) pada pokoknya berisi...", o:["Perintah mengambil tindakan yang perlu untuk memulihkan keamanan dan ketertiban","Penyerahan jabatan Presiden secara penuh kepada Letjen Soeharto","Pembubaran DPR Gotong Royong","Pengangkatan Presiden seumur hidup","Penetapan pemilu dipercepat"], p:"Supersemar adalah surat perintah dari Presiden Soekarno kepada Letjen Soeharto untuk mengambil tindakan yang diperlukan demi memulihkan keamanan dan ketertiban. Isinya bukan penyerahan jabatan Presiden."},
{t:"sejarah", q:"Tuntutan Tritura tahun 1966 yang berkaitan dengan bidang ekonomi adalah...", o:["Turunkan harga dan perbaiki ekonomi","Bubarkan PKI","Rombak Kabinet Dwikora","Laksanakan pemilu","Cabut Dekrit Presiden"], p:"Tritura (Tiga Tuntutan Rakyat) berisi: bubarkan PKI, rombak Kabinet Dwikora dari unsur PKI, dan turunkan harga. Hanya tuntutan ketiga yang bersifat ekonomi."},
{t:"sejarah", q:"Berikut ini yang merupakan salah satu tuntutan Reformasi 1998 adalah...", o:["Penghapusan dwifungsi ABRI","Kembali ke UUD Sementara 1950","Peningkatan peran militer dalam pemerintahan","Penambahan masa jabatan Presiden","Penerapan demokrasi terpimpin"], p:"Tuntutan Reformasi 1998 antara lain penghapusan dwifungsi ABRI, amandemen UUD 1945, supremasi hukum, pemberantasan KKN, dan pemberian otonomi daerah seluas-luasnya. Pilihan lain justru berlawanan dengan semangat reformasi."},
{t:"sejarah", q:"Semboyan “Ing madya mangun karsa” dari Ki Hajar Dewantara, pendiri Taman Siswa, bermakna...", o:["Di tengah memberi semangat dan membangun kemauan","Di depan memberi teladan","Di belakang memberi dorongan","Di atas memberi perintah","Di samping mengawasi"], p:"Tiga semboyannya: Ing ngarsa sung tuladha (di depan memberi teladan), Ing madya mangun karsa (di tengah membangun semangat), Tut wuri handayani (di belakang memberi dorongan). Taman Siswa didirikan tahun 1922."},
{t:"nasionalisme", q:"Berikut ini dampak positif globalisasi bagi bangsa Indonesia adalah...", o:["Kemudahan akses informasi dan teknologi untuk memajukan ilmu pengetahuan","Menurunnya rasa gotong royong","Masuknya budaya asing tanpa disaring","Meningkatnya gaya hidup konsumtif","Melemahnya kebanggaan terhadap produk lokal"], p:"Dampak positif globalisasi antara lain kemudahan akses informasi, teknologi, dan kerja sama antarnegara. Empat pilihan lain termasuk dampak negatif."},
{t:"nasionalisme", q:"Dampak negatif globalisasi di bidang sosial budaya adalah...", o:["Lunturnya nilai gotong royong akibat gaya hidup individualis","Meningkatnya kerja sama pendidikan antarnegara","Berkembangnya teknologi komunikasi","Terbukanya peluang ekspor produk","Bertambahnya lapangan kerja dari investasi"], p:"Globalisasi dapat menggeser nilai dan budaya lokal, misalnya gotong royong, karena gaya hidup asing yang individualis. Pilihan lain adalah dampak positif."},
{t:"nasionalisme", q:"Sikap yang tepat dalam menghadapi arus globalisasi adalah...", o:["Menyaring budaya asing dengan nilai Pancasila dan mengambil yang positif","Menerima semua budaya asing agar tidak ketinggalan zaman","Menutup diri dari semua pengaruh luar","Meniru gaya hidup asing sepenuhnya","Menolak teknologi baru karena berasal dari luar negeri"], p:"Bangsa yang kuat tidak menolak globalisasi sepenuhnya dan tidak pula menelannya mentah-mentah. Pancasila menjadi filter untuk mengambil yang bermanfaat dan menolak yang merugikan."},
{t:"nasionalisme", q:"Pancasila berbeda dari liberalisme dan komunisme karena Pancasila...", o:["Menyeimbangkan kepentingan individu dan masyarakat serta mengakui Ketuhanan","Mengutamakan kebebasan individu di atas kepentingan bersama","Menghapus hak milik pribadi demi masyarakat tanpa kelas","Menolak semua gagasan dari luar negeri","Hanya mengakui kepentingan negara"], p:"Liberalisme menekankan kebebasan individu, komunisme menghapus hak milik pribadi dan tidak mengakui Tuhan. Pancasila menempatkan keduanya secara seimbang dan berlandaskan Ketuhanan Yang Maha Esa."},
{t:"nasionalisme", q:"Sikap yang tepat ketika menerima pesan berantai yang belum jelas kebenarannya adalah...", o:["Memeriksa sumbernya dan memverifikasi sebelum membagikan","Langsung meneruskannya agar semua orang waspada","Meneruskannya jika isinya menarik","Meneruskannya jika dikirim teman dekat","Mengabaikannya dan membiarkannya beredar"], p:"Hoaks menyebar karena orang membagikan tanpa memeriksa. Verifikasi sumber dan data lebih dahulu adalah inti literasi digital, bukan sekadar meneruskan atau membiarkan."},
{t:"nasionalisme", q:"Berikut ini ciri berita hoaks adalah...", o:["Judul provokatif, sumber tidak jelas, dan tanpa rujukan data","Memuat data dan narasumber yang dapat diverifikasi","Mencantumkan penanggung jawab redaksi yang jelas","Memuat bantahan dan klarifikasi resmi","Menyampaikan fakta secara berimbang"], p:"Hoaks biasanya memakai judul yang memancing emosi, tidak menyebut sumber, dan tidak punya rujukan yang bisa dicek. Pilihan lain justru ciri informasi yang kredibel."},
{t:"nasionalisme", q:"Wujud nasionalisme di bidang ekonomi yang tepat adalah...", o:["Mengutamakan penggunaan produk dalam negeri yang berkualitas","Menolak seluruh produk impor dalam bentuk apa pun","Membeli produk luar negeri agar dianggap modern","Membeli barang bajakan karena murah","Menimbun barang dalam negeri untuk dijual mahal"], p:"Cinta produk dalam negeri berarti mendukung produsen lokal dengan membeli produk yang berkualitas. Menolak semua impor tidak realistis, sedangkan barang bajakan dan penimbunan merugikan ekonomi."},
{t:"integritas", q:"Pakta integritas yang ditandatangani pejabat berisi...", o:["Komitmen tertulis menjauhi korupsi, kolusi, dan nepotisme serta siap menerima sanksi","Pemberian kewenangan tambahan kepada pejabat","Jaminan kenaikan jabatan","Anjuran tanpa konsekuensi apa pun","Aturan yang hanya berlaku bagi pegawai swasta"], p:"Pakta integritas adalah pernyataan tertulis yang mengikat penandatangan untuk bersih dari KKN dan bersedia dikenai sanksi bila melanggar. Fungsinya mengikat, bukan sekadar anjuran."},
{t:"integritas", q:"Komisi Pemberantasan Korupsi dibentuk dengan UU Nomor 30 Tahun 2002 yang kemudian diubah dengan Undang-Undang Nomor...", o:["19 Tahun 2019","20 Tahun 2001","31 Tahun 1999","28 Tahun 1999","5 Tahun 2014"], p:"UU KPK (30/2002) diubah dengan UU Nomor 19 Tahun 2019 sebagai perubahan kedua (perubahan pertama lewat UU 10/2015 yang menetapkan Perppu 1/2015). UU 31/1999 dan 20/2001 mengatur tindak pidana korupsi, UU 28/1999 tentang penyelenggara negara bersih KKN, dan UU 5/2014 tentang ASN (kini diganti UU 20/2023)."},
{t:"integritas", q:"Ciri utama pemimpin yang berintegritas adalah...", o:["Satunya kata dan perbuatan serta konsisten pada nilai yang benar meski tidak diawasi","Selalu mengikuti kehendak atasan","Menjaga citra di depan publik meski berbeda dengan tindakan sebenarnya","Mengutamakan kelompoknya agar tetap loyal","Menghindari keputusan sulit agar tidak dikritik"], p:"Integritas berarti konsisten antara ucapan dan tindakan, juga ketika tidak ada yang mengawasi. Mengejar citra, loyalitas kelompok, atau menghindar dari keputusan sulit bukan ciri integritas."},
{t:"integritas", q:"Seorang ASN sering datang terlambat dengan dalih macet padahal berangkat mendekati jam masuk. Sikap yang sesuai integritas adalah...", o:["Mengakui kesalahan dan berangkat lebih awal agar tiba tepat waktu","Tetap beralasan macet karena atasan memaklumi","Meminta rekan memanipulasi data absensi","Tidak mempermasalahkannya selama pekerjaan selesai","Meminta jam kerja diubah khusus untuk dirinya"], p:"Integritas menuntut kejujuran mengakui kesalahan dan memperbaikinya, bukan mencari dalih. Penyebabnya adalah berangkat terlalu mepet, sehingga solusinya berangkat lebih awal."},
{t:"integritas", q:"Seorang kerabat meminta Anda, anggota panitia seleksi pegawai, meloloskan anaknya yang nilainya kurang. Sikap Anda...", o:["Menolak dengan sopan dan menjelaskan bahwa seleksi dinilai sesuai aturan","Meloloskannya asal tidak ketahuan","Meloloskannya sebagai balas budi dan merahasiakannya","Mengubah sedikit nilainya agar tidak mencolok","Meneruskan permintaan ke panitia lain"], p:"Menerima titipan berarti nepotisme dan melanggar asas seleksi yang objektif. Menolak dengan sopan dan menjelaskan aturan menjaga hubungan sekaligus integritas."},
{t:"bahasa", q:"Bacalah paragraf berikut.\n“Banyak warga mengeluh karena lampu jalan di permukiman padam setiap malam. Beberapa orang mengaku takut melintas saat pulang kerja. Anak-anak pun tidak lagi bermain di luar setelah magrib. Dengan demikian, penerangan jalan yang buruk berdampak pada rasa aman warga.”\nIde pokok paragraf tersebut adalah...", o:["Penerangan jalan yang buruk berdampak pada rasa aman warga","Warga mengeluh karena lampu jalan padam","Anak-anak tidak lagi bermain di luar setelah magrib","Warga takut pulang kerja pada malam hari","Pemerintah harus segera memperbaiki lampu jalan"], p:"Paragraf ini induktif: contoh-contoh di awal diakhiri kalimat simpulan yang menjadi ide pokok, ditandai “Dengan demikian”. Pilihan lain hanya berupa kalimat penjelas."},
{t:"bahasa", q:"Bacalah paragraf berikut.\n“Pegawai yang rutin berolahraga cenderung jarang jatuh sakit. Mereka juga lebih fokus dan tidak mudah lelah saat bekerja. Sebaliknya, pegawai yang kurang bergerak lebih sering izin karena sakit.”\nSimpulan yang tepat dari paragraf tersebut adalah...", o:["Kebiasaan berolahraga berkaitan dengan kesehatan dan produktivitas kerja pegawai","Semua pegawai wajib berolahraga setiap hari","Pegawai yang sakit pasti kurang bergerak","Olahraga dapat menggantikan pengobatan medis","Pegawai yang jarang izin pasti rajin berolahraga"], p:"Simpulan harus sesuai isi teks tanpa melebih-lebihkan. Paragraf hanya menyebut kaitan olahraga dengan kesehatan dan kinerja, bukan kewajiban atau hubungan sebab-akibat mutlak."},
{t:"bahasa", q:"Bacalah paragraf berikut.\n(1) Pasar tradisional masih menjadi tempat belanja utama bagi banyak keluarga. (2) Harga barang di sana relatif murah dan dapat ditawar. (3) Pedagang dan pembeli sering terlibat percakapan yang akrab. (4) Teknologi komputer terus berkembang pesat di berbagai bidang. (5) Karena itu, pasar tradisional tetap diminati.\nKalimat yang tidak padu dalam paragraf tersebut adalah...", o:["Kalimat (4)","Kalimat (1)","Kalimat (2)","Kalimat (3)","Kalimat (5)"], p:"Paragraf membahas alasan pasar tradisional tetap diminati. Kalimat (4) tentang perkembangan teknologi komputer tidak berkaitan dengan topik itu sehingga merusak kepaduan."},
{t:"bahasa", q:"Bacalah paragraf berikut.\n(1) Dinas kesehatan mengadakan penyuluhan tentang pentingnya mencuci tangan. (2) Para peserta penyuluhan itu terdiri dari para ibu-ibu rumah tangga. (3) Peserta mempraktikkan enam langkah mencuci tangan yang benar. (4) Setelah penyuluhan, mereka membagikan pengetahuan itu kepada tetangga. (5) Kegiatan ini diharapkan dapat menurunkan angka penyakit diare.\nKalimat yang tidak efektif dalam paragraf tersebut adalah...", o:["Kalimat (2)","Kalimat (1)","Kalimat (3)","Kalimat (4)","Kalimat (5)"], p:"Kalimat (2) tidak efektif karena pleonasme: “para” dan “ibu-ibu” sama-sama menyatakan jamak, dan “terdiri dari” seharusnya “terdiri atas”. Kalimat lain sudah ringkas dan jelas."},
{t:"bahasa", q:"Bacalah paragraf berikut.\n“Kepala desa mengumpulkan warga di balai desa. Ia menjelaskan bahwa masih banyak warga yang keras kepala menolak membayar iuran sampah. Padahal, iuran itu dipakai untuk menggaji petugas kebersihan.”\nMakna ungkapan keras kepala pada paragraf tersebut adalah...", o:["Sulit menerima nasihat dan tetap pada pendiriannya","Memiliki kepala yang keras","Bertubuh kuat dan tegap","Berpikir lambat","Mudah marah"], p:"Keras kepala adalah ungkapan yang berarti tidak mau menurut atau tidak mudah dinasihati. Dalam konteks paragraf, warga menolak membayar iuran meski sudah dijelaskan manfaatnya."},
{t:"bahasa", q:"Bacalah paragraf berikut.\n“Sejumlah sekolah di daerah terpencil belum memiliki akses internet yang stabil. Hal itu menyebabkan siswa kesulitan mengikuti pembelajaran daring. Akibatnya, nilai mereka cenderung menurun.”\nFrasa Hal itu pada kalimat kedua merujuk pada...", o:["Sejumlah sekolah di daerah terpencil belum memiliki akses internet yang stabil","Siswa kesulitan mengikuti pembelajaran daring","Nilai siswa cenderung menurun","Pembelajaran daring di daerah terpencil","Sekolah-sekolah di perkotaan"], p:"Kata rujukan “hal itu” menunjuk kalimat sebelumnya. Penyebab siswa kesulitan belajar daring adalah belum adanya akses internet stabil di sekolah, bukan akibatnya."},
{t:"bahasa", q:"Bacalah paragraf berikut.\n“Sampah rumah tangga yang dibuang ke sungai menyebabkan air tercemar. Pencemaran itu mengancam kehidupan ikan dan kesehatan warga yang memakai air sungai. Di sisi lain, pemilahan sampah dari rumah dapat mengurangi jumlah sampah yang berakhir di sungai.”\nKalimat penutup yang tepat untuk paragraf tersebut adalah...", o:["Oleh karena itu, setiap keluarga sebaiknya membiasakan memilah sampah sebelum membuangnya.","Sungai adalah sumber kehidupan yang sangat penting bagi manusia.","Pemerintah harus menutup semua pabrik di tepi sungai.","Banyak ikan di sungai mati setiap tahun.","Air sungai tampak berwarna cokelat saat musim hujan."], p:"Kalimat penutup yang baik menyimpulkan atau menindaklanjuti isi paragraf. Pesan paragraf adalah memilah sampah dari rumah untuk menjaga sungai, sehingga ajakan membiasakan memilah sampah paling sesuai."},
{t:"bahasa", q:"Bacalah paragraf berikut.\n(1) Pada hari Senin, kepala dinas mengadakan rapat dengan para staf. (2) Rapat itu membahas pelayanan publik di seluruh kecamatan. (3) Para staf diminta menyampaikan kendala yang dihadapi dilapangan. (4) Hasilnya akan dilaporkan kepada atasan.\nPerbaikan yang tepat untuk kalimat (3) adalah...", o:["dilapangan menjadi di lapangan","dihadapi menjadi di hadapi","diminta menjadi di minta","staf menjadi staff","kendala menjadi kendalah"], p:"Kata depan “di” yang menunjukkan tempat ditulis terpisah: “di lapangan”. “Dihadapi” dan “diminta” adalah kata kerja pasif sehingga ditulis serangkai, dan “staf” adalah bentuk baku."}
];

const BANK_TIU_V2 = [
{t:"bacaan", q:"Bacalah paragraf berikut.\n“Tidur yang cukup membantu tubuh memulihkan diri. Saat tidur, sel-sel yang rusak diperbaiki dan daya tahan tubuh diperkuat. Kurang tidur dalam jangka panjang justru meningkatkan risiko berbagai penyakit.”\nIde pokok paragraf tersebut adalah...", o:["Tidur yang cukup penting bagi kesehatan tubuh","Kurang tidur menyebabkan penyakit kronis","Sel yang rusak diperbaiki saat seseorang tidur","Daya tahan tubuh orang dewasa lebih kuat daripada anak-anak","Tidur siang lebih bermanfaat daripada tidur malam"], p:"Seluruh kalimat membahas manfaat tidur bagi tubuh, sehingga ide pokoknya adalah pentingnya tidur yang cukup. Pilihan lain hanya sebagian detail atau tidak disebut di teks."},
{t:"bacaan", q:"Bacalah paragraf berikut.\n“Mangrove di pesisir berfungsi menahan abrasi dan menjadi tempat berkembang biak ikan serta udang. Namun, luas hutan mangrove terus berkurang karena dialihkan menjadi tambak dan permukiman. Di beberapa daerah, warga mulai menanam kembali mangrove secara bergotong royong.”\nPernyataan yang sesuai dengan isi paragraf tersebut adalah...", o:["Pengalihan lahan menjadi salah satu penyebab berkurangnya hutan mangrove","Mangrove hanya bermanfaat bagi pembudidaya tambak","Seluruh daerah pesisir telah menanam kembali mangrove","Penanaman mangrove dilakukan pemerintah tanpa melibatkan warga","Abrasi pantai tidak berkaitan dengan keberadaan mangrove"], p:"Teks menyebut mangrove berkurang karena dialihkan menjadi tambak dan permukiman. Pilihan lain bertentangan dengan teks atau melebih-lebihkan (misalnya “seluruh daerah”)."},
{t:"bacaan", q:"Bacalah paragraf berikut.\n“Inflasi adalah kenaikan harga barang dan jasa secara umum dan terus-menerus. Ketika inflasi tinggi, daya beli masyarakat menurun karena uang yang sama hanya dapat membeli barang lebih sedikit. Karena itu, bank sentral berupaya menjaga inflasi tetap rendah dan stabil.”\nPernyataan yang TIDAK sesuai dengan isi paragraf tersebut adalah...", o:["Inflasi yang tinggi membuat daya beli masyarakat meningkat","Inflasi merupakan kenaikan harga barang dan jasa secara umum","Bank sentral berupaya menjaga inflasi tetap stabil","Inflasi tinggi mengurangi jumlah barang yang dapat dibeli dengan uang yang sama","Inflasi yang tinggi menjadi hal yang ingin dihindari bank sentral"], p:"Teks menyatakan inflasi tinggi justru menurunkan daya beli. Pernyataan yang menyebut daya beli meningkat bertentangan dengan teks, sedangkan empat pilihan lain sesuai."},
{t:"bacaan", q:"Bacalah paragraf berikut.\n“Aplikasi pembayaran digital memudahkan transaksi tanpa uang tunai. Namun, pengguna yang kurang berhati-hati mudah menjadi korban penipuan melalui tautan palsu. Kasus kehilangan saldo pun banyak terjadi karena pengguna membagikan kode verifikasi kepada orang lain.”\nSimpulan yang tepat dari paragraf tersebut adalah...", o:["Kemudahan pembayaran digital harus diimbangi kewaspadaan pengguna menjaga data pribadi","Pembayaran digital sebaiknya dihindari","Penipuan hanya terjadi pada pengguna pembayaran digital","Uang tunai selalu lebih aman daripada pembayaran digital","Aplikasi pembayaran digital sering menghilangkan saldo penggunanya"], p:"Teks menyebut manfaat sekaligus risiko yang muncul karena kelalaian pengguna. Simpulan yang tepat adalah kemudahan itu perlu diimbangi kehati-hatian, bukan menolak atau menyalahkan aplikasinya."},
{t:"bacaan", q:"Bacalah paragraf berikut.\n“Antrean panjang di kantor pelayanan sering membuat warga enggan mengurus dokumen. Padahal, pendaftaran secara daring telah tersedia dan dapat dilakukan dari rumah. Dengan memanfaatkannya, waktu tunggu dapat dipangkas dan petugas pun dapat melayani lebih banyak orang.”\nTujuan penulis paragraf tersebut adalah...", o:["Mengajak warga memanfaatkan pendaftaran daring untuk mengurangi antrean","Mengkritik petugas yang lambat melayani","Menjelaskan sejarah pelayanan publik","Menginformasikan jumlah warga yang mengantre setiap hari","Meminta kantor pelayanan menambah jumlah loket"], p:"Penulis menyebut masalah antrean lalu menawarkan solusi pendaftaran daring beserta manfaatnya. Tujuannya mengajak pembaca memakai layanan itu, bukan mengkritik petugas atau meminta loket tambahan."},
{t:"bacaan", q:"Bacalah paragraf berikut.\n“Imunisasi dasar diberikan pada bayi untuk membentuk kekebalan terhadap penyakit tertentu. Jika cakupan imunisasi di suatu wilayah tinggi, penularan penyakit dapat ditekan sehingga anak yang belum diimunisasi pun ikut terlindungi. Sebaliknya, cakupan yang rendah membuka peluang munculnya wabah.”\nPernyataan yang TIDAK sesuai dengan isi paragraf tersebut adalah...", o:["Cakupan imunisasi yang tinggi memperbesar peluang munculnya wabah","Imunisasi dasar diberikan pada bayi","Cakupan imunisasi yang tinggi dapat menekan penularan penyakit","Anak yang belum diimunisasi dapat ikut terlindungi bila cakupan tinggi","Cakupan imunisasi yang rendah membuka peluang munculnya wabah"], p:"Teks menyatakan cakupan tinggi menekan penularan dan cakupan rendah membuka peluang wabah. Pernyataan bahwa cakupan tinggi memperbesar peluang wabah berkebalikan dengan isi teks."},
{t:"bacaan", q:"Bacalah paragraf berikut.\n“Usaha mikro dan kecil menyerap banyak tenaga kerja di berbagai daerah. Pelaku usaha ini juga menjaga perputaran uang di tingkat lokal. Meskipun skalanya kecil, sumbangannya terhadap perekonomian tidak dapat diabaikan.”\nIde pokok paragraf tersebut adalah...", o:["Usaha mikro dan kecil berperan penting bagi perekonomian","Usaha mikro menyerap lebih banyak tenaga kerja daripada perusahaan besar","Perputaran uang lokal dijaga oleh pemerintah daerah","Skala usaha yang kecil menghambat pertumbuhan ekonomi","Pelaku usaha mikro perlu mendapat modal dari pemerintah"], p:"Tiga kalimat sama-sama menunjukkan peran penting usaha mikro dan kecil. Perbandingan dengan perusahaan besar, peran pemerintah, dan modal tidak disebut dalam teks."},
{t:"bacaan", q:"Bacalah paragraf berikut.\n“Kota yang memiliki banyak ruang terbuka hijau cenderung bersuhu lebih sejuk. Pepohonan menyerap polusi dan menyediakan tempat warga berolahraga. Sebaliknya, kawasan yang dipenuhi beton menyimpan panas dan membuat udara terasa pengap.”\nSimpulan yang tepat dari paragraf tersebut adalah...", o:["Ruang terbuka hijau berdampak baik bagi kenyamanan dan kesehatan warga kota","Beton harus dilarang dalam pembangunan kota","Semua kota sebaiknya dibangun tanpa gedung","Pepohonan hanya berguna untuk menyerap polusi","Warga kota jarang berolahraga karena udara pengap"], p:"Teks memuat manfaat ruang hijau (sejuk, bersih, tempat olahraga) dan dampak buruk kawasan beton. Simpulan wajar adalah ruang hijau bermanfaat bagi kenyamanan dan kesehatan; larangan beton atau gedung tidak disebut."},
{t:"bacaan", q:"Bacalah paragraf berikut.\n“Kecerdasan buatan kini dipakai untuk membantu dokter membaca hasil rontgen dengan lebih cepat. Meski demikian, keputusan akhir tentang diagnosis tetap berada di tangan dokter. Teknologi ini dipandang sebagai alat bantu, bukan pengganti tenaga medis.”\nPernyataan yang sesuai dengan isi paragraf tersebut adalah...", o:["Diagnosis akhir pasien tetap diputuskan oleh dokter","Kecerdasan buatan telah menggantikan seluruh tenaga medis","Dokter tidak lagi diperlukan untuk membaca rontgen","Kecerdasan buatan menentukan diagnosis akhir pasien","Pembacaan rontgen menjadi lebih lambat dengan bantuan teknologi"], p:"Teks menyatakan keputusan akhir diagnosis tetap di tangan dokter. Pilihan lain bertentangan karena teknologi hanya alat bantu dan membuat pembacaan lebih cepat."},
{t:"bacaan", q:"Bacalah paragraf berikut.\n“Banyak pemerintah daerah membuka kanal pengaduan secara daring agar warga mudah menyampaikan keluhan. Setiap aduan dicatat dan diteruskan kepada unit yang berwenang. Warga dapat memantau perkembangan penanganan aduannya melalui nomor tiket.”\nPernyataan yang TIDAK sesuai dengan isi paragraf tersebut adalah...", o:["Aduan warga hanya dapat disampaikan dengan datang langsung ke kantor","Kanal pengaduan dibuka secara daring","Aduan diteruskan kepada unit yang berwenang","Warga dapat memantau penanganan aduannya","Setiap aduan warga dicatat"], p:"Teks menyebut kanal pengaduan dibuka secara daring, jadi pernyataan bahwa aduan hanya bisa disampaikan langsung bertentangan dengan teks. Empat pilihan lain disebut jelas."},
{t:"bacaan", q:"Bacalah paragraf berikut.\n“Konsumsi gula berlebih berkaitan dengan meningkatnya kasus diabetes pada usia muda. Satu kaleng minuman manis dapat mengandung gula melebihi batas anjuran harian. Karena itu, label kandungan gula pada kemasan sebaiknya dibaca sebelum membeli.”\nTujuan penulis paragraf tersebut adalah...", o:["Mengimbau pembaca agar membaca label kandungan gula sebelum membeli minuman","Melarang penjualan minuman manis","Menjelaskan proses pembuatan minuman kemasan","Mempromosikan minuman rendah gula tertentu","Membandingkan harga minuman manis dari berbagai merek"], p:"Setelah menyampaikan risiko gula, penulis menutup dengan anjuran membaca label sebelum membeli. Jadi tujuannya mengimbau pembaca, bukan melarang atau mempromosikan produk."},
{t:"bacaan", q:"Bacalah paragraf berikut.\n“Pengolahan sampah organik menjadi kompos mengurangi volume sampah yang dikirim ke tempat pembuangan akhir. Kompos kemudian dapat dipakai untuk menyuburkan tanaman di pekarangan. Dengan cara ini, rumah tangga turut mengurangi masalah sampah sekaligus menghemat biaya pupuk.”\nPernyataan yang sesuai dengan isi paragraf tersebut adalah...", o:["Pengomposan di rumah tangga dapat menghemat biaya pupuk","Kompos hanya cocok untuk tanaman di sawah","Sampah anorganik dapat dijadikan kompos","Tempat pembuangan akhir menolak semua sampah organik","Pengolahan kompos wajib dilakukan oleh pemerintah"], p:"Kalimat terakhir teks menyebut rumah tangga dapat menghemat biaya pupuk. Pilihan lain tidak disebut atau bertentangan, misalnya kompos dibuat dari sampah organik dan dipakai di pekarangan."},
{t:"bacaan", q:"Bacalah paragraf berikut.\n“Harga cabai naik tajam ketika hujan deras merusak tanaman di sentra produksi. Pasokan ke pasar berkurang, sedangkan permintaan tetap. Saat pasokan turun pada permintaan yang stabil, harga cenderung naik.”\nSimpulan yang tepat dari paragraf tersebut adalah...", o:["Penurunan pasokan pada permintaan yang tetap mendorong kenaikan harga","Hujan deras selalu menyebabkan kelangkaan semua bahan pangan","Pedagang sengaja menaikkan harga saat musim hujan","Permintaan cabai turun saat musim hujan","Petani cabai sebaiknya berhenti menanam"], p:"Teks menjelaskan rantai sebab: hujan merusak tanaman, pasokan turun, permintaan tetap, harga naik. Simpulannya adalah pasokan yang turun pada permintaan tetap mendorong harga naik; pilihan lain tidak didukung teks."},
{t:"bacaan", q:"Bacalah paragraf berikut.\n“Keterbukaan informasi anggaran membuat masyarakat dapat ikut mengawasi penggunaan dana publik. Warga dapat memeriksa rincian belanja melalui situs resmi pemerintah daerah. Pengawasan semacam ini mendorong aparat lebih berhati-hati dalam mengelola anggaran.”\nIde pokok paragraf tersebut adalah...", o:["Keterbukaan informasi anggaran memungkinkan masyarakat mengawasi dana publik","Situs resmi pemerintah daerah memuat banyak informasi","Aparat harus lebih berhati-hati mengelola anggaran","Masyarakat wajib memeriksa seluruh belanja pemerintah","Anggaran daerah selalu diselewengkan"], p:"Kalimat pertama menjadi gagasan utama: keterbukaan anggaran memungkinkan pengawasan publik. Kalimat berikutnya hanya cara dan dampaknya, sedangkan pilihan lain tidak disebut."},
{t:"analitis", q:"Lima pegawai (Raka, Sekar, Taufik, Ulfa, Wahyu) mengantre di loket, urutan 1 paling depan. Diketahui:\n• Sekar berada lebih depan daripada Taufik.\n• Ulfa berada tepat di belakang Wahyu.\n• Raka berada di urutan kedua.\n• Taufik bukan yang terakhir.\nSiapa yang berada di urutan keempat?", o:["Wahyu","Raka","Sekar","Taufik","Ulfa"], p:"Raka urutan 2. Wahyu-Ulfa harus berurutan di urutan 3-4 atau 4-5. Pada 3-4, Sekar dan Taufik mengisi urutan 1 dan 5 sehingga Taufik terakhir (dilarang). Maka susunannya Sekar, Raka, Taufik, Wahyu, Ulfa dan urutan keempat adalah Wahyu."},
{t:"analitis", q:"Lima orang (Fira, Gani, Hesti, Imam, Joni) menempati lantai 1 sampai 5 sebuah gedung, satu orang per lantai. Diketahui:\n• Fira tinggal di lantai yang lebih tinggi daripada Gani.\n• Hesti tinggal di lantai 3.\n• Imam tinggal tepat di atas Fira.\n• Joni tidak tinggal di lantai 1.\nSiapa yang tinggal di lantai 5?", o:["Imam","Fira","Gani","Hesti","Joni"], p:"Hesti di lantai 3. Fira-Imam harus berurutan (Imam tepat di atas Fira) dengan Fira di atas Gani, sehingga pasangan itu berada di lantai 4-5 dan Gani di lantai 1 atau 2. Karena Joni bukan lantai 1, Gani lantai 1 dan Joni lantai 2, sehingga lantai 5 dihuni Imam."},
{t:"analitis", q:"Lima orang (Kiki, Lina, Maya, Nita, Oka) bertugas jaga Senin sampai Jumat, satu orang per hari. Diketahui:\n• Kiki bertugas sebelum Lina.\n• Maya bertugas pada hari Rabu.\n• Nita bertugas tepat sehari setelah Lina.\n• Oka bertugas pada hari Selasa.\nSiapa yang bertugas pada hari Jumat?", o:["Nita","Kiki","Lina","Maya","Oka"], p:"Maya Rabu dan Oka Selasa. Sisa hari adalah Senin, Kamis, dan Jumat. Nita tepat setelah Lina hanya mungkin Kamis-Jumat, sehingga Kiki bertugas Senin dan Jumat dipegang Nita."},
{t:"analitis", q:"Lima orang (Putri, Rani, Sandi, Tono, Umar) duduk sebaris pada kursi 1 sampai 5 dari kiri ke kanan. Diketahui:\n• Putri duduk di salah satu ujung.\n• Sandi duduk di kursi 5.\n• Tono duduk tepat di antara Rani dan Umar.\n• Rani duduk lebih ke kiri daripada Umar.\nSiapa yang duduk di kursi 4?", o:["Umar","Putri","Rani","Sandi","Tono"], p:"Sandi di kursi 5, sehingga Putri (ujung) di kursi 1. Rani, Tono, Umar mengisi kursi 2-4 dengan Tono di tengah, dan Rani di kiri Umar. Susunannya Putri, Rani, Tono, Umar, Sandi, jadi kursi 4 ditempati Umar."},
{t:"analitis", q:"Lima siswa (Vina, Wati, Yoga, Zaki, Alya) diurutkan dari tertinggi (peringkat 1) sampai terpendek. Diketahui:\n• Wati lebih tinggi dari Vina.\n• Yoga lebih pendek dari Vina.\n• Zaki lebih tinggi dari Wati.\n• Alya lebih pendek dari Yoga.\nSiapa yang berada di peringkat 3?", o:["Vina","Wati","Yoga","Zaki","Alya"], p:"Dari keempat syarat terbentuk rantai Zaki > Wati > Vina > Yoga > Alya. Rantai ini menentukan seluruh urutan, sehingga peringkat 3 adalah Vina."},
{t:"analitis", q:"Lima orang (Bayu, Cahya, Dian, Erik, Farah) duduk mengelilingi meja bundar, kursi 1 sampai 5 searah jarum jam (kursi 5 bersebelahan dengan kursi 1). Diketahui:\n• Bayu duduk di kursi 1.\n• Cahya tidak bersebelahan dengan Bayu.\n• Dian duduk tepat setelah Cahya searah jarum jam.\n• Erik bersebelahan dengan Bayu.\n• Farah tidak bersebelahan dengan Bayu.\nSiapa yang duduk di kursi 5?", o:["Dian","Bayu","Cahya","Erik","Farah"], p:"Bayu di kursi 1, sehingga Cahya hanya bisa di kursi 3 atau 4. Jika Cahya di kursi 3 (Dian 4), Erik dan Farah harus mengisi kursi 2 dan 5 yang sama-sama bersebelahan dengan Bayu, melanggar syarat Farah. Jadi Cahya di kursi 4, Dian di kursi 5, Erik kursi 2, Farah kursi 3."}
];

const BANK_TKP_2 = [
{a:"profesional", q:"Saat pekerjaan menumpuk menjelang tenggat, saya...", o:[["menyusun prioritas, mengerjakannya berurutan, dan melapor jika berisiko terlambat",5],["menyusun prioritas lalu mengerjakan tugas yang paling mendesak sampai selesai tepat waktu",4],["mengerjakan tugas sesuai urutan datangnya",3],["mengerjakan yang mudah dahulu dan menunda yang sulit",2],["membiarkannya menumpuk sampai atasan menegur saya",1]], p:"Prioritas yang jelas plus pelaporan dini membuat pekerjaan tuntas dan atasan tidak terkejut. Mengerjakan sesuai urutan datang bersifat normatif, sedangkan menunda atau menunggu teguran menunjukkan tidak bertanggung jawab."},
{a:"profesional", q:"Ketika mendapat tugas baru yang belum saya kuasai, saya...", o:[["belajar mandiri, bertanya ke senior, lalu meminta umpan balik",5],["mempelajari panduan dan contoh pekerjaan sebelumnya hingga saya bisa mengerjakannya",4],["menunggu arahan atasan tentang cara mengerjakannya",3],["meminta tugas itu diberikan kepada rekan yang lebih mampu",2],["mengerjakannya seadanya tanpa bertanya agar tidak terlihat kurang paham",1]], p:"Belajar sendiri sambil bertanya dan meminta umpan balik menunjukkan sikap proaktif dan hasil yang terjamin. Menunggu arahan bersifat pasif, sedangkan melempar tugas atau mengerjakan seadanya merugikan pekerjaan."},
{a:"profesional", q:"Saat rekan mengkritik hasil kerja saya, saya...", o:[["menyimak kritiknya, memperbaiki hasil kerja, dan berterima kasih",5],["menyimak kritiknya dan memperbaiki bagian hasil kerja yang memang masih kurang",4],["mencatat kritik itu dan mempertimbangkannya nanti",3],["membela hasil kerja saya dengan menjelaskan alasannya",2],["mengabaikannya karena merasa pekerjaan saya sudah benar",1]], p:"Kritik adalah bahan perbaikan, sehingga langsung memperbaiki dan menghargai masukan adalah sikap terbaik. Hanya mencatat itu pasif, sementara membela diri atau mengabaikan menutup peluang berkembang."},
{a:"profesional", q:"Saya ditugaskan menggantikan sementara pekerjaan rekan yang sedang cuti panjang. Saya...", o:[["mempelajari catatan serah terimanya, menuntaskan pekerjaan sesuai jadwal, dan mencatat perkembangannya untuk diserahkan kembali",5],["mempelajari catatan serah terimanya lalu mengerjakan bagian yang paling mendesak dengan baik",4],["mengerjakan bagian yang sudah ada petunjuknya saja",3],["menunda pekerjaan itu sampai rekan saya kembali bekerja",2],["mengerjakannya asal selesai karena bukan pekerjaan saya sendiri",1]], p:"Tugas pengganti tetap menjadi tanggung jawab penuh: dipelajari, dituntaskan, dan dicatat agar mudah diserahkan kembali. Menunda atau mengerjakan asal-asalan merugikan layanan."},
{a:"profesional", q:"Jika ada kesempatan studi lanjut dengan biaya sendiri, saya...", o:[["mengurus izin belajar, mengambilnya di luar jam kerja, dan menerapkan ilmunya di kantor",5],["mengambilnya di luar jam kerja agar pekerjaan kantor tidak terganggu sama sekali",4],["mempertimbangkannya jika kantor mendukung",3],["menundanya sampai kondisi keuangan benar-benar nyaman",2],["mengabaikannya karena merasa ilmu saya sudah cukup",1]], p:"Pengembangan diri yang berizin, tidak mengganggu tugas, dan bermanfaat bagi instansi adalah sikap profesional terbaik. Menunda atau merasa cukup menunjukkan kurangnya motivasi berkembang."},
{a:"profesional", q:"Saat usia saya mendekati pensiun, saya...", o:[["tetap bekerja optimal dan mewariskan pengetahuan kerja kepada penerus",5],["tetap bekerja optimal dan disiplin sampai masa pensiun benar-benar tiba",4],["bekerja seperti biasa tanpa tambahan upaya",3],["mengurangi usaha karena sebentar lagi berhenti",2],["mengerjakan urusan pribadi pada jam kerja karena merasa sudah senior",1]], p:"Profesionalisme tidak berhenti menjelang pensiun, dan menyiapkan penerus menjaga kesinambungan layanan. Mengurangi usaha atau memakai jam kerja untuk urusan pribadi melanggar tanggung jawab."},
{a:"profesional", q:"Saya mengetahui rekan satu tim memanipulasi data laporan. Saya...", o:[["memastikan faktanya, menegur rekan itu, lalu melapor jika tidak diperbaiki",5],["menegur rekan itu dan memintanya segera memperbaiki data laporan yang salah",4],["mencatat temuan itu dan menunggu situasi yang tepat",3],["tidak ikut campur selama bagian saya benar",2],["ikut memakai data itu agar laporan tim cepat selesai",1]], p:"Data palsu merugikan instansi sehingga perlu dipastikan, ditegur, lalu dilaporkan bila tidak diperbaiki. Membiarkan atau ikut memakainya melanggar integritas dan aturan."},
{a:"profesional", q:"Ketika target kerja bulanan tampak sulit tercapai, saya...", o:[["menganalisis kendala, menyusun strategi baru, dan berkonsultasi",5],["mencari penyebab kendalanya lalu menambah usaha agar target tetap tercapai",4],["terus bekerja seperti biasa sambil berharap target tercapai",3],["meminta atasan menurunkan target",2],["mengubah angka laporan agar target terlihat tercapai",1]], p:"Mengidentifikasi kendala dan mencari strategi bersama atasan menunjukkan sikap solutif. Menurunkan target menghindari tanggung jawab, dan mengubah angka adalah kecurangan."},
{a:"profesional", q:"Saat kantor menerapkan prosedur kerja baru, saya...", o:[["segera mempelajarinya, menerapkannya, dan membantu rekan yang belum paham",5],["mempelajarinya dan menerapkannya dengan benar",4],["mempelajari bagian yang berkaitan dengan tugas saya saja",3],["menunggu rekan lain menerapkannya lebih dahulu",2],["tetap memakai cara lama karena sudah terbiasa",1]], p:"Adaptasi cepat disertai membantu rekan membuat perubahan berjalan lancar. Menunggu atau bertahan pada cara lama menghambat unit kerja."},
{a:"profesional", q:"Sore hari saya baru sadar ada tugas yang terlupa, padahal tenggatnya besok pagi. Saya...", o:[["segera mengerjakannya sampai selesai, memeriksa hasilnya, dan memasang pengingat agar tidak terulang",5],["segera mengerjakannya sampai selesai sebelum tenggat tiba",4],["mengerjakan semampunya lalu mengumpulkannya apa adanya",3],["meminta perpanjangan waktu dengan alasan pekerjaan sedang banyak",2],["mengaku sudah mengirimnya padahal belum dikerjakan",1]], p:"Kelalaian ditebus dengan tindakan cepat, hasil yang diperiksa, dan pengingat agar tidak terulang. Mencari dalih untuk menunda atau berbohong soal pengiriman melanggar integritas."},
{a:"pelayanan", q:"Sistem layanan daring kantor mendadak gangguan, sementara warga mulai menumpuk di ruang tunggu. Saya...", o:[["mengumumkan gangguan dengan jelas, melayani secara manual sesuai prosedur, dan melaporkannya ke petugas TI",5],["melayani warga secara manual sambil menunggu sistem kembali pulih",4],["meminta warga menunggu sampai sistem kembali normal",3],["menyarankan warga datang lagi besok tanpa kepastian",2],["menutup loket tanpa pemberitahuan sampai sistem pulih",1]], p:"Warga perlu kejelasan dan layanan tetap berjalan lewat cara manual, sementara gangguan dilaporkan agar cepat ditangani. Menyuruh pulang tanpa kepastian atau menutup loket diam-diam merugikan warga."},
{a:"pelayanan", q:"Seorang warga mengadu bahwa petugas di loket sebelah bersikap tidak sopan kepadanya. Saya...", o:[["meminta maaf, membantu menyelesaikan keperluannya, lalu meneruskan aduannya kepada atasan sesuai prosedur",5],["meminta maaf atas sikap rekan saya dan membantu menyelesaikan keperluannya",4],["menyarankannya menulis aduan di kotak saran",3],["membela rekan saya dengan alasan ia sedang lelah",2],["menceritakan aduan itu kepada rekan lain sebagai bahan gunjingan",1]], p:"Aduan ditangani dengan empati, keperluan warga dituntaskan, lalu dilaporkan lewat jalur resmi agar menjadi perbaikan. Membela rekan tanpa dasar atau menggunjingkan aduan tidak menyelesaikan masalah."},
{a:"pelayanan", q:"Seorang warga marah karena layanan terasa lambat. Saya...", o:[["mendengarkan, meminta maaf, mempercepat layanan, dan melaporkan penyebab keterlambatan",5],["mendengarkan keluhannya dengan sabar lalu mempercepat layanan agar urusannya segera selesai",4],["meminta ia bersabar karena semua orang mengantre",3],["meminta rekan lain menghadapi warga itu",2],["membalas dengan nada tinggi agar ia tenang",1]], p:"Empati disertai tindakan dan pelaporan penyebab memperbaiki layanan jangka panjang. Menyuruh sabar atau melempar ke rekan tidak menyelesaikan masalah."},
{a:"pelayanan", q:"Warga tidak memahami formulir pelayanan yang harus diisi. Saya...", o:[["membantu mengisinya dan mengusulkan formulir yang lebih sederhana",5],["membantu mengisinya dengan sabar sampai seluruh bagian formulir selesai",4],["menunjukkan contoh pengisian yang tertempel di dinding",3],["meminta ia bertanya kepada warga lain",2],["menolak berkasnya karena formulir belum benar",1]], p:"Membantu langsung sekaligus mengusulkan perbaikan formulir menyelesaikan masalah di akarnya. Menolak berkas karena kesalahan formulir menyulitkan warga."},
{a:"pelayanan", q:"Pengunjung mengeluh bahwa petunjuk arah di kantor membingungkan. Saya...", o:[["mengantar pengunjung itu dan mengusulkan perbaikan papan petunjuk kepada pimpinan",5],["mengantar pengunjung itu ke tempat yang dituju",4],["menjelaskan arah secara lisan",3],["mengatakan ia dapat melihat petunjuk yang tersedia",2],["mengabaikan keluhan itu karena bukan wewenang saya",1]], p:"Menolong saat itu juga dan memperbaiki sumber masalah adalah pelayanan paling tuntas. Menyalahkan pengunjung atau mengabaikan keluhan tidak mencerminkan sikap melayani."},
{a:"pelayanan", q:"Seorang warga mengirim pesan ke nomor pribadi saya pada malam hari untuk menanyakan persyaratan layanan. Saya...", o:[["menjawab singkat dengan ramah, mengarahkannya ke kanal layanan resmi, dan menindaklanjutinya pada jam kerja",5],["mengarahkannya dengan ramah ke kanal layanan resmi kantor",4],["membalas pesannya keesokan hari pada jam kerja",3],["membiarkan pesannya tanpa jawaban",2],["meminta imbalan karena dilayani di luar jam kerja",1]], p:"Warga tetap dilayani dengan ramah, tetapi diarahkan ke kanal resmi dan ditindaklanjuti pada jam kerja agar layanannya tercatat. Mengabaikan pesan atau meminta imbalan merugikan warga dan melanggar aturan."},
{a:"jejaring", q:"Saya mendapati unit saya dan unit lain menjalankan program yang hampir sama untuk sasaran yang sama. Saya...", o:[["menghubungi unit itu, membandingkan rencana kedua program, dan mengusulkan kepada atasan agar perannya dibagi atau digabung",5],["menghubungi unit itu untuk saling berbagi informasi tentang program masing-masing",4],["tetap menjalankan program unit saya sesuai rencana semula",3],["merahasiakan rencana program unit saya agar tidak ditiru unit lain",2],["menjelekkan program unit lain di depan atasan",1]], p:"Program yang tumpang tindih memboroskan anggaran. Berkoordinasi dan mengusulkan pembagian peran membuat kerja sama efektif, sedangkan merahasiakan rencana atau menjelekkan unit lain merusak jejaring kerja."},
{a:"jejaring", q:"Rekan dari unit lain meminta bantuan di luar tugas rutin saya. Saya...", o:[["membantu setelah tugas saya selesai dan memberi tahu atasan agar koordinasinya jelas",5],["membantu sepanjang tidak mengganggu pekerjaan utama yang menjadi tanggung jawab saya",4],["membantu hanya jika atasan memintanya",3],["menyarankannya mencari bantuan lain",2],["menolak karena itu bukan urusan unit saya",1]], p:"Kerja sama lintas unit dibangun dengan membantu tanpa mengabaikan tugas sendiri dan tetap berkoordinasi dengan atasan. Menunggu disuruh bersifat pasif, sedangkan menolak mentah-mentah merusak jejaring kerja."},
{a:"jejaring", q:"Dalam rapat lintas instansi, usulan saya ditolak peserta lain. Saya...", o:[["mendengarkan alasannya, menyesuaikan usulan, dan mencari titik temu",5],["mendengarkan alasan mereka dan menerima keputusan rapat dengan lapang dada",4],["diam dan mengikuti keputusan rapat",3],["menyampaikan keberatan hanya kepada rekan dekat setelah rapat",2],["memaksakan usulan sampai peserta lain mengalah",1]], p:"Mencari titik temu menghasilkan keputusan terbaik dan menjaga hubungan antarinstansi. Memaksakan kehendak merusak kerja sama."},
{a:"jejaring", q:"Saya mengikuti pelatihan bersama peserta dari berbagai instansi. Saya...", o:[["aktif berdiskusi, bertukar kontak, dan menjaga komunikasi untuk peluang kerja sama setelah pelatihan",5],["aktif berdiskusi dan bertukar pengalaman dengan peserta lain selama pelatihan",4],["berbicara dengan peserta lain jika berada dalam satu kelompok",3],["hanya bergaul dengan rekan dari instansi saya sendiri",2],["meremehkan peserta dari instansi yang saya anggap kurang penting",1]], p:"Pelatihan bersama adalah kesempatan membangun jejaring yang berguna bagi kerja sama berikutnya. Menutup diri pada kelompok sendiri atau meremehkan instansi lain menyia-nyiakan kesempatan itu."},
{a:"jejaring", q:"Saya ditunjuk menjadi narahubung unit saya dalam kegiatan bersama beberapa instansi. Saya...", o:[["menyusun daftar kontak, menyampaikan informasi tepat waktu kepada semua pihak, dan memastikan setiap pertanyaan terjawab",5],["menyampaikan informasi kegiatan kepada semua pihak secara tepat waktu",4],["menjawab pertanyaan hanya jika ada yang menghubungi saya",3],["meneruskan semua pertanyaan kepada atasan tanpa menindaklanjutinya",2],["hanya memberi informasi kepada instansi yang saya kenal dekat",1]], p:"Narahubung yang baik proaktif menyebarkan informasi dan memastikan semua pihak terlayani. Melempar pertanyaan atau pilih kasih merusak koordinasi antarinstansi."},
{a:"sosbud", q:"Dalam obrolan di ruang kerja, rekan-rekan sering memakai bahasa daerah sehingga rekan dari daerah lain tidak dapat ikut berbicara. Saya...", o:[["beralih ke bahasa Indonesia, mengajak rekan itu ikut berbincang, dan mengingatkan rekan lain dengan santun",5],["beralih ke bahasa Indonesia setiap kali rekan itu ikut dalam obrolan",4],["menerjemahkan isi obrolan hanya jika ia bertanya",3],["tetap memakai bahasa daerah karena ia nanti akan terbiasa sendiri",2],["sengaja memakai bahasa daerah agar ia tidak memahami pembicaraan kami",1]], p:"Di lingkungan kerja yang beragam, bahasa Indonesia mempersatukan sehingga semua orang dapat terlibat. Terus atau sengaja memakai bahasa yang tidak dipahami rekan membuatnya terkucil."},
{a:"sosbud", q:"Tetangga saya seorang lansia yang tinggal sendirian dan sudah beberapa hari tidak terlihat keluar rumah. Saya...", o:[["mendatangi rumahnya untuk memastikan keadaannya, membantu bila perlu, dan mengabari keluarganya atau pengurus RT",5],["mendatangi rumahnya untuk menanyakan keadaannya",4],["menanyakan keadaannya kepada tetangga lain",3],["menunggu sampai ia terlihat keluar rumah lagi",2],["menggunjingkan kebiasaannya yang jarang bergaul kepada tetangga lain",1]], p:"Kepedulian sosial berarti memastikan langsung keadaan tetangga yang rentan dan melibatkan keluarga atau pengurus lingkungan. Menunggu atau menggunjingkannya tidak menunjukkan kepedulian."},
{a:"sosbud", q:"Kantor merayakan hari besar keagamaan yang berbeda dari agama saya, dan saya diminta membantu urusan teknis kepanitiaan. Saya...", o:[["menerima, mengerjakan tugas teknis dengan sungguh-sungguh, dan mengajak rekan lain ikut membantu",5],["menerima dan mengerjakan tugas teknis yang diberikan kepada saya",4],["membantu hanya jika tidak ada panitia lain yang bersedia",3],["mencari alasan agar tidak dilibatkan",2],["menolak sambil menyindir perayaan agama tersebut",1]], p:"Membantu urusan teknis perayaan agama lain tanpa mengikuti ritual ibadahnya adalah wujud toleransi dan kebersamaan di kantor. Mencari alasan menghindar atau menyindir merusak kerukunan."},
{a:"sosbud", q:"Seorang rekan satu ruangan baru saja kehilangan anggota keluarganya. Saya...", o:[["menyampaikan belasungkawa, melayat bila memungkinkan, dan membantu pekerjaannya sementara ia izin",5],["menyampaikan belasungkawa secara langsung dan ikut melayat",4],["mengirim ucapan belasungkawa lewat grup kantor",3],["tidak menanggapi karena saya tidak terlalu akrab dengannya",2],["mengeluhkan pekerjaannya yang terbengkalai selama ia izin",1]], p:"Empati ditunjukkan lewat kehadiran dan bantuan nyata agar rekan dapat berduka dengan tenang. Bersikap acuh atau mengeluhkan pekerjaannya tidak menunjukkan kepedulian."},
{a:"sosbud", q:"Seorang rekan sering tidak diajak dalam kegiatan bersama karena berasal dari keluarga kurang mampu. Saya...", o:[["mengajaknya bergabung, menegur rekan lain dengan santun, dan mengusulkan kegiatan yang terjangkau bagi semua",5],["mengajaknya ikut serta dalam kegiatan bersama berikutnya",4],["bersikap biasa kepadanya tanpa ikut mengucilkan",3],["membiarkannya karena sudah menjadi kebiasaan kelompok",2],["ikut menjauhinya agar saya tetap diterima kelompok",1]], p:"Menghargai sesama tidak memandang latar belakang ekonomi. Melibatkannya dan menegur perilaku mengucilkan menumbuhkan kebersamaan, sedangkan membiarkan atau ikut menjauhi adalah diskriminasi."},
{a:"tik", q:"Saya kesulitan mengingat kata sandi berbagai akun kantor. Saya...", o:[["membuat kata sandi kuat yang berbeda untuk tiap akun dan menyimpannya di pengelola kata sandi yang diizinkan kantor",5],["membuat kata sandi kuat yang berbeda untuk tiap akun",4],["memakai satu kata sandi kuat untuk semua akun",3],["memakai kata sandi sederhana seperti tanggal lahir",2],["membagikan kata sandi kepada rekan agar mereka bisa mengingatkan saya",1]], p:"Kata sandi yang kuat, berbeda untuk tiap akun, dan disimpan dengan aman melindungi sistem kantor. Kata sandi sederhana atau dibagikan kepada orang lain membuka celah pembobolan."},
{a:"tik", q:"Saya harus meninggalkan meja sebentar, sementara layar komputer masih menampilkan data pribadi warga. Saya...", o:[["menyimpan pekerjaan, mengunci layar, dan menyalakan penguncian otomatis bila belum aktif",5],["mengunci layar komputer sebelum meninggalkan meja",4],["mematikan monitornya saja",3],["membiarkannya karena hanya pergi sebentar",2],["meminta pengunjung yang sedang menunggu menjaga komputer saya",1]], p:"Data pribadi warga wajib dilindungi meski ditinggal sebentar. Mengunci layar dan menyalakan penguncian otomatis mencegah akses orang lain, sedangkan membiarkan layar terbuka atau menitipkannya kepada orang luar membahayakan data."},
{a:"tik", q:"Saya perlu menerjemahkan dokumen internal kantor yang bersifat terbatas, dan tersedia layanan penerjemah daring gratis. Saya...", o:[["memakai sarana resmi kantor atau menerjemahkannya sendiri, dan bertanya ke pengelola TI bila ragu",5],["menerjemahkan sendiri bagian yang diperlukan tanpa mengunggah dokumennya",4],["meminta rekan yang mahir bahasa asing menerjemahkannya",3],["mengunggah sebagian isi dokumen yang menurut saya tidak terlalu penting",2],["mengunggah seluruh dokumen ke layanan itu agar cepat selesai",1]], p:"Dokumen internal tidak boleh diunggah ke layanan publik karena isinya dapat tersimpan dan bocor. Gunakan sarana resmi kantor atau kerjakan sendiri; mengunggah sebagian maupun seluruh isinya melanggar keamanan informasi."},
{a:"tik", q:"Pekerjaan saya memerlukan aplikasi pengolah gambar, dan seorang teman menawarkan versi bajakan untuk dipasang di laptop kantor. Saya...", o:[["menolak, mengajukan aplikasi berlisensi lewat prosedur kantor, dan sementara memakai aplikasi gratis yang legal",5],["menolak dan memakai aplikasi gratis yang legal",4],["menunggu kantor menyediakan aplikasinya",3],["memasangnya di laptop pribadi lalu memindahkan hasilnya ke laptop kantor",2],["memasang versi bajakan itu di laptop kantor",1]], p:"Perangkat lunak bajakan melanggar hukum dan rawan memuat program jahat. Mengajukan aplikasi berlisensi dan memakai alternatif legal menjaga keamanan perangkat kantor."},
{a:"tik", q:"Saya lupa memperbarui sistem keamanan laptop kantor. Saya...", o:[["segera memperbarui, mengaktifkan pembaruan otomatis, dan mengingatkan rekan lain",5],["segera memperbaruinya hari itu juga",4],["memperbaruinya saat ada waktu luang",3],["menunggu laptop mengingatkan lagi",2],["menonaktifkan pemberitahuan agar tidak mengganggu",1]], p:"Pembaruan menutup celah keamanan, sehingga dilakukan segera dan dijadikan rutin. Menunda atau mematikan pemberitahuan membuat data kantor rentan."},
{a:"antiradikal", q:"Di grup kantor beredar ajakan menyumbang untuk yayasan tidak jelas yang diduga mendanai kelompok kekerasan. Saya...", o:[["tidak menyumbang, mengingatkan rekan agar memeriksa yayasan itu, dan melaporkan dugaan tersebut kepada pimpinan atau aparat berwenang",5],["tidak menyumbang dan mengingatkan rekan agar berhati-hati",4],["tidak menyumbang dan tidak menanggapi ajakan itu",3],["menyumbang sekadarnya agar tidak dianggap tidak peduli",2],["ikut menyumbang dan menyebarkan ajakan itu ke grup lain",1]], p:"Mendanai kelompok kekerasan dapat termasuk tindak pidana pendanaan terorisme. Menolak, mengingatkan rekan, dan melapor lewat jalur resmi memutus aliran dana, sedangkan menyumbang atau menyebarkan ajakannya justru membantu kelompok itu."},
{a:"antiradikal", q:"Saya melihat rekan menyebar ujaran kebencian terhadap kelompok warga tertentu di media sosial. Saya...", o:[["menegurnya, meminta unggahan dihapus, dan melaporkannya bila tidak diindahkan",5],["menegurnya dan meminta unggahan dihapus",4],["tidak ikut menanggapi unggahan itu",3],["membiarkan karena itu akunnya sendiri",2],["memberi tanda suka agar tidak dikucilkan",1]], p:"Ujaran kebencian merusak persatuan, sehingga perlu ditegur dan dilaporkan bila berlanjut. Membiarkan atau mendukungnya ikut memperkuat perpecahan."},
{a:"antiradikal", q:"Di grup warga, seseorang membagikan video cara merakit bahan peledak disertai ajakan melawan aparat. Saya...", o:[["tidak menyebarkannya, menyimpan buktinya, meminta admin menghapusnya, dan melaporkannya kepada aparat berwenang",5],["meminta admin grup segera menghapus video itu",4],["tidak menonton dan tidak menanggapi video itu",3],["keluar dari grup tanpa memberi tahu siapa pun",2],["meneruskan video itu ke grup lain agar banyak yang tahu",1]], p:"Konten yang mengajarkan kekerasan harus dihentikan penyebarannya dan dilaporkan kepada aparat disertai bukti. Diam, keluar dari grup, apalagi meneruskannya tidak mencegah bahaya."},
{a:"antiradikal", q:"Dalam diskusi, rekan saya menilai musyawarah tidak perlu lagi dipakai dalam mengambil keputusan. Saya...", o:[["menyampaikan pandangan berbeda dengan santun berdasarkan Pancasila dan menjaga diskusi sehat",5],["menyampaikan pandangan saya dengan santun",4],["hanya mendengarkan tanpa menanggapi",3],["mengganti topik ke hal lain",2],["meninggalkan diskusi dengan marah",1]], p:"Pandangan keliru diluruskan dengan dialog santun berlandaskan Pancasila, termasuk sila keempat tentang musyawarah. Menghindar atau marah tidak menyelesaikan masalah."},
{a:"antiradikal", q:"Seorang anggota keluarga mulai menutup diri dan menolak bergaul dengan orang yang berbeda pandangan. Saya...", o:[["mengajaknya berdialog, beraktivitas sosial bersama, dan meminta bantuan pihak berwenang bila perlu",5],["mengajaknya berdialog dan beraktivitas bersama",4],["membiarkan sampai ia mau berbicara sendiri",3],["menjauhinya agar tidak terpengaruh",2],["memarahinya di depan orang banyak",1]], p:"Pendekatan dialog dan aktivitas bersama menumbuhkan kembali keterbukaan, dengan bantuan pihak berwenang jika perlu. Menjauhi atau mempermalukannya memperburuk keadaan."}
];
